    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 dim1,
    .param .u32 dim2
)
{
    .reg .pred   %p;
    .reg .u32    %tid_x, %block_x, %blockDim_x;
    .reg .u32    %tid, %total;
    .reg .u64    %input, %output;
    .reg .u32    %batch, %dim1, %dim2;
    .reg .u32    %batch_idx, %dim2_idx, %stride0, %elem_index;
    .reg .u64    %in_ptr, %out_ptr, %byte_offset, %out_byte_offset;
    .reg .u32    %i, %tmp, %tmp2;
    .reg .f16    %fval, %mean_h;
    .reg .f32    %acc, %f32, %mean_f, %dim1_f;

    // Load kernel arguments
    ld.param.u64 %input,   [input_ptr];
    ld.param.u64 %output,  [output_ptr];
    ld.param.u32 %batch,   [batch];
    ld.param.u32 %dim1,    [dim1];
    ld.param.u32 %dim2,    [dim2];

    // Compute global thread id
    mov.u32 %tid_x,      %tid.x;
    mov.u32 %block_x,    %ctaid.x;
    mov.u32 %blockDim_x, %ntid.x;
    mad.lo.u32 %tid, %block_x, %blockDim_x, %tid_x;

    // Guard against excess threads
    mul.lo.u32 %total, %batch, %dim2;
    setp.ge.u32 %p, %tid, %total;
    @%p bra DONE;

    // Derive (batch, dim2) coordinates
    div.u32 %batch_idx, %tid, %dim2;
    mul.lo.u32 %tmp, %batch_idx, %dim2;
    sub.u32 %dim2_idx, %tid, %tmp;

    // Compute stride for the first dimension (dim1 * dim2)
    mul.lo.u32 %stride0, %dim1, %dim2;

    // Base element index for this thread (first dim1 slice)
    mul.lo.u32 %elem_index, %batch_idx, %stride0;
    add.u32 %elem_index, %elem_index, %dim2_idx;

    // Convert element index to byte offset (fp16 = 2 bytes) and address input
    mul.wide.u32 %byte_offset, %elem_index, 2;
    add.u64 %in_ptr, %input, %byte_offset;

